begin;
do $curate$ declare bid uuid;begin
if exists(select 1 from businesses where website ilike '%moorequalitypest.com%' or lower(name)=lower('Moore Quality Pest Control') or regexp_replace(coalesce(phone,''),'[^0-9]','','g') like '%2093901313') then raise exception 'Duplicate requires review';end if;
insert into businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values('Moore Quality Pest Control','Home Services','Tracy',null,'(209) 390-1313','https://moorequalitypest.com/','Tracy-based provider advertising residential and commercial pest control. Its official service-area page individually names Mountain House, Tracy, Lathrop and Manteca. Confirm the specific pest, property eligibility, treatment scope, required credentials, quote and appointment directly. Website information does not establish treatment safety, effectiveness or current availability.','approved',true,false,null,0,'editorial_first_party','https://moorequalitypest.com/services/service-area/','first_party_website_desk_check',now()) returning id into bid;
insert into listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,'https://moorequalitypest.com/services/service-area/',array['identity','website','public phone','advertised pest control','explicit named service cities'],array['Mountain House','Tracy','Lathrop','Manteca'],array['pest control'],'Official website information checked November 8, 2026. No owner contact, independent license/insurance/quality/safety/effectiveness check, photos, price or appointment confirmation. No street address or local branch inferred. Sources: https://moorequalitypest.com/ https://moorequalitypest.com/services/service-area/');
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,'{"name": "Moore Quality Pest Control", "city": "Tracy", "phone": "(209) 390-1313", "website": "https://moorequalitypest.com/", "source_url": "https://moorequalitypest.com/services/service-area/", "areas": ["Mountain House", "Tracy", "Lathrop", "Manteca"], "tags": ["pest control"], "description": "Tracy-based provider advertising residential and commercial pest control. Its official service-area page individually names Mountain House, Tracy, Lathrop and Manteca. Confirm the specific pest, property eligibility, treatment scope, required credentials, quote and appointment directly. Website information does not establish treatment safety, effectiveness or current availability."}'::jsonb,'Explicit four-city pest service website evidence','https://moorequalitypest.com/services/service-area/');end $curate$;
do $curate$ declare bid uuid;begin
